const inputItems = $input.all();
const isQueue = inputItems.length === 1 && inputItems[0].json && inputItems[0].json.id && Array.isArray(inputItems[0].json.listings);
const isHttpError = !isQueue && inputItems.length === 1 && inputItems[0].json && inputItems[0].json.error;
let rawCards;
if (isQueue) {
  // manual batch from listing_queue (pasted from the browser when the scrape is blocked)
  rawCards = inputItems[0].json.listings;
} else if (isHttpError) {
  rawCards = [];
} else if (inputItems.length === 1 && Array.isArray(inputItems[0].json)) {
  // n8n wrapped the whole Apify dataset-items array into one item's json
  rawCards = inputItems[0].json;
} else {
  // n8n auto-split the JSON array response into one item per element
  rawCards = inputItems.map(i => i.json);
}
const listings = rawCards
  .filter(c => c && c.mls_id)
  .map(c => ({
    mls_id: String(c.mls_id),
    address: c.address || null,
    price: c.price || null,
    beds: c.beds || null,
    baths: c.baths || null,
    sqft: c.sqft || null,
    url: c.url || null,
    photo_thumb_url: c.photo_thumb_url || null,
  }));
return [{ json: { scrape_error: !!isHttpError, from_queue: !!isQueue, listings } }];

const seen = new Set();
const parsed = ($('Parse Listings').first().json.listings || []).filter(l => {
  if (seen.has(l.mls_id)) return false;
  seen.add(l.mls_id);
  return true;
}); // newest-first, from the scrape, de-duped by mls_id
const sentIds = new Set($input.all().map(i => i.json.mls_id).filter(id => id != null));

let selected = parsed.filter(l => !sentIds.has(l.mls_id));
let usedFallback = false;
if (selected.length === 0) {
  selected = parsed.slice(0, 10);
  usedFallback = true;
} else {
  selected = selected.slice(0, 10);
}

const esc = (s) => String(s == null ? '' : s).replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/'/g, '&#39;');
const sqlEsc = (s) => String(s == null ? '' : s).replace(/'/g, "''"); // SQL-literal escape — see docs/lessons-learned.md re: apostrophes in scraped/user text breaking raw query interpolation
const fullPhoto = (thumbUrl) => thumbUrl ? thumbUrl.replace('/thumbnails/', '/') : null;

const cards = selected.map((l) => {
  const photo = fullPhoto(l.photo_thumb_url);
  const photoBlock = photo ? `<tr><td style='padding:0;'><img src='${esc(photo)}' alt='${esc(l.address || 'Listing')}' width='600' style='display:block;width:100%;max-width:600px;height:auto;'></td></tr>` : '';
  const priceBlock = l.price ? `<div style='font-size:14px;color:#3A3F48;margin-top:4px;'>${esc(l.price)}</div>` : '';
  const detailsParts = [l.beds ? esc(l.beds) + ' Bed' + (String(l.beds) === '1' ? '' : 's') : null, l.baths ? esc(l.baths) + ' Bath' + (String(l.baths) === '1' ? '' : 's') : null, l.sqft ? esc(l.sqft) + ' Sq.Ft.' : null].filter(Boolean).join(' &middot; ');
  const detailsBlock = detailsParts ? `<div style='font-size:13px;color:#6A6F78;margin-top:2px;'>${detailsParts}</div>` : '';
  return `<table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='margin:0 0 18px;border:1px solid #e5e4de;border-radius:8px;overflow:hidden;'>${photoBlock}<tr><td style='padding:14px 16px;'><div style='font-size:16px;font-weight:bold;color:#0A0F1A;'>${esc(l.address || 'New Listing')}</div>${priceBlock}${detailsBlock}<div style='margin-top:12px;'><a href='${esc(l.url)}' style='display:inline-block;background:#0A0F1A;color:#ffffff;text-decoration:none;font-size:14px;font-weight:bold;padding:10px 18px;border-radius:6px;'>View Listing &rarr;</a></div></td></tr></table>`;
}).join('');

const listingsForSql = selected.map(l => ({ mls_id: sqlEsc(l.mls_id), address: sqlEsc(l.address) }));

return [{ json: { cards_html: cards, listing_count: selected.length, listings: listingsForSql, used_fallback: usedFallback } }];

const cardsHtml = $('Build Cards').first().json.cards_html || '';
const EVAN = 'ded234e3-1c78-45c3-8924-6036e1fcaf60';
const MICH = '451306d1-6437-42b8-8ffe-c16f28803490';
const agents = {};
agents[EVAN] = { name: 'Evan Knutson', phone: '507-210-9140', email: 'eknutson@teamyellownow.com', photo: 'https://tools.norrai.co/weichert_evan_headshot.jpg' };
agents[MICH] = { name: 'Michelle Jasinski', phone: '507-210-7967', email: 'mjasinski@teamyellownow.com', photo: 'https://tools.norrai.co/weichert_michelle_headshot.jpg' };
const BASE = 'https://norrai.app.n8n.cloud/webhook/marketing-opt-out';
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.email) continue;
  const a = agents[j.client_id] || agents[EVAN];
  const firstName = String(j.lead_name || '').trim().split(/\s+/)[0] || 'there';
  const optOut = BASE + '?lead_id=' + encodeURIComponent(j.id) + '&token=' + encodeURIComponent(j.opt_out_token || '');
  const html = `<!DOCTYPE html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'></head><body style='margin:0;padding:0;background:#f4f4f2;font-family:Arial,Helvetica,sans-serif;color:#0A0F1A;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#f4f4f2;padding:24px 0;'><tr><td align='center'><table role='presentation' width='600' cellpadding='0' cellspacing='0' style='max-width:600px;width:100%;background:#ffffff;border-radius:10px;overflow:hidden;'><tr><td style='background:#ffce00;padding:22px 28px;'><div style='font-size:18px;font-weight:bold;color:#0A0F1A;'>Weichert, Realtors&reg; &mdash; Heartland</div><div style='font-size:12px;color:#3A3F48;letter-spacing:.04em;'>FARIBAULT, MINNESOTA</div></td></tr><tr><td style='padding:24px 28px 8px;'><p style='margin:0 0 8px;font-size:16px;'>Hi ${firstName},</p><p style='margin:0;font-size:15px;line-height:1.6;color:#3A3F48;'>Here are this week&rsquo;s featured listings in Faribault.</p></td></tr><tr><td style='padding:8px 28px 0;'>${cardsHtml}</td></tr><tr><td style='padding:0 28px;'><p style='margin:8px 0 0;font-size:15px;line-height:1.6;'>Interested in a showing? Call or text <strong>${a.name}</strong> at <a href='tel:${a.phone}' style='color:#1a73a7;'>${a.phone}</a>.</p></td></tr><tr><td style='padding:18px 28px 20px;'><table role='presentation' cellpadding='0' cellspacing='0'><tr><td style='width:56px;padding-right:12px;vertical-align:top;'><img src='${a.photo}' width='56' height='56' alt='${a.name}' style='display:block;width:56px;height:56px;border-radius:50%;object-fit:cover;'></td><td style='vertical-align:top;'><div style='font-size:14px;font-weight:bold;'>${a.name}</div><div style='font-size:13px;color:#3A3F48;'>Weichert, Realtors&reg; &mdash; Heartland</div><div style='font-size:13px;'><a href='tel:${a.phone}' style='color:#1a73a7;'>${a.phone}</a> &middot; <a href='mailto:${a.email}' style='color:#1a73a7;'>${a.email}</a></div></td></tr></table></td></tr><tr><td style='padding:16px 28px 24px;background:#fafaf7;border-top:1px solid #eee;'><p style='margin:0;font-size:11px;color:#9EA3AA;line-height:1.6;'>You are receiving this because you are a contact of ${a.name} at Weichert, Realtors&reg; &mdash; Heartland in Faribault, MN.<br><a href='${optOut}' style='color:#9EA3AA;text-decoration:underline;'>Opt out of future listing emails</a></p></td></tr></table></td></tr></table></body></html>`;
  out.push({ json: { email: j.email, lead_name: j.lead_name || '', subject: 'Featured listings this week — ' + a.name, html, agent_name: a.name, agent_email: a.email, client_id: j.client_id } });
}
return out;

